+ // Computes C = A * B. C is NOT zeroed by the caller. Any number of threads may be
+ // used (std::thread is available); n is any size from 1 to 2048.
+ // Optimized implementation using i-k-j order, NEON vectorization, cache blocking,
+ // and multithreading over row blocks.
+ namespace {
+     static constexpr int BLOCK = 64; // tile size for i and j loops
+     static constexpr int MAX_THREADS = 8; // maximum number of threads to use
+ }
+ extern "C" void matmul(int n, const float* A, const float* B, float* C) {
+     // Zero C before computation
+     std::fill(C, C + static_cast<size_t>(n) * n, 0.0f);
+
+     // Determine number of i-blocks
+     const int num_i_blocks = (n + BLOCK - 1) / BLOCK;
+     const int threads = std::min(MAX_THREADS, num_i_blocks);
+     std::vector<std::thread> workers;
+     workers.reserve(threads);
+
+     // Split i-blocks among threads
+     int block_per_thread = num_i_blocks / threads;
+     int remainder = num_i_blocks % threads;
+     int start_block = 0;
+     for (int t = 0; t < threads; ++t) {
+         int block_count = block_per_thread + (t < remainder ? 1 : 0);
+         int i0 = start_block * BLOCK;
+         int i_end = std::min(i0 + block_count * BLOCK, n);
+         workers.emplace_back([&, i0, i_end]() {
+             // Process rows i in [i0, i_end)
+             for (int i0_local = i0; i0_local < i_end; i0_local += BLOCK) {
+                 int i_end_local = std::min(i0_local + BLOCK, n);
+                 for (int j0 = 0; j0 < n; j0 += BLOCK) {
+                     int j_end = std::min(j0 + BLOCK, n);
+                     for (int k = 0; k < n; ++k) {
+                         for (int i = i0_local; i < i_end_local; ++i) {
+                             float a = A[i * n + k];
+                             int j = j0;
+                             // Vectorized inner j loop
+                             for (; j + 3 < j_end; j += 4) {
+#if defined(__ARM_NEON)
+                                 float32x4_t b = vld1q_f32(&B[k * n + j]);
+                                 float32x4_t c = vld1q_f32(&C[i * n + j]);
+                                 c = vfmaq_f32(c, b, vdupq_n_f32(a));
+                                 vst1q_f32(&C[i * n + j], c);
+#else
+                                 // Scalar fallback (should not happen on Apple Silicon)
+                                 C[i * n + j]     += a * B[k * n + j];
+                                 C[i * n + j + 1] += a * B[k * n + j + 1];
+                                 C[i * n + j + 2] += a * B[k * n + j + 2];
+                                 C[i * n + j + 3] += a * B[k * n + j + 3];
+#endif
+                             }
+                             // Remainder scalar loop
+                             for (; j < j_end; ++j) {
+                                 C[i * n + j] += a * B[k * n + j];
+                             }
+                         }
+                     }
+                 }
+             }
+         });
+         start_block += block_count;
+     }
+     for (auto& th : workers) th.join();
+ }
 // OMEGA-BLOCK-END
